// Home "Components" stage, client-only: the server renders ShowcasePreview (the live panel's markup as static JSX,
// generated by scripts/showcase-preview.ts), so `/` carries no resume state for the ui components. The first pointer,
// focus or touch on the stage swaps in the live panel (Showcase.tsx); its code loads then. A focus that caused the
// swap moves to the same control in the live panel.
import { signal } from "@rivetjs/reactivity";
import { Showcase } from "./Showcase.tsx";
import { ShowcasePreview } from "./ShowcasePreview.tsx";

/** Controls the keyboard can reach, in the same order in preview and live panel. */
const FOCUSABLE = "button, input:not([tabindex='-1']), select:not([tabindex='-1']), [tabindex='0']";

export function ShowcaseStage() {
  const live = signal(false);
  return (
    <div
      class="lp-stage"
      data-ui-theme="rivet"
      onPointerOver={() => live.set(true)}
      onTouchStart={() => live.set(true)}
      onFocusIn={(event) => {
        if (live()) return;
        const stage = (event.target as Element).closest(".lp-stage")!;
        const controls = () => [...stage.querySelectorAll<HTMLElement>(FOCUSABLE)];
        const index = controls().indexOf(event.target as HTMLElement);
        live.set(true);
        if (index >= 0) requestAnimationFrame(() => setTimeout(() => controls()[index]?.focus()));
      }}
    >
      {live() ? <Showcase /> : <ShowcasePreview />}
    </div>
  );
}
